-- Din Felsefesi 2, bahar 7. hafta: yeniden yazılan Zapoot ve Quiz soruları (yeni paketler). Kaynak: docs/soru-onerileri/yeni/bahar-07.txt. Aynı soru metni varsa atlanır.
do $$
declare v_icerik uuid;
begin
  select id into v_icerik from public.subjects where ad = 'Din Felsefesi 2' limit 1;
  if v_icerik is null then raise exception 'Din Felsefesi 2 içeriği bulunamadı'; end if;
  insert into public.questions (subject_id, soru, dogru, yanlislar, sure_sn, ek)
