  from (select string_to_array(l, '|') as p from unnest(string_to_array($q$
7|Z|Din dilinin pratik hayattaki fonksiyonuna bakarak yapılan çözümleme hangi adla anılır?|Konatif çözümleme|Kognitif çözümleme|Tarihî çözümleme|Estetik çözümleme|Konatif çözümleme|orta|Hatırlama
